    Lemma fail_fin : forall msF mo mc (r : rv) Fx mw bw ew xg ng j6 slv (q ev loc : Z),
      as_AKREL H s (mkCfg msF mo) -> as_MPRES H mo0 mo ->
      as_VIS H s msF = MS (mkRr r) Fx (Z_to_bv 64 0xff1bc) fc None mc (seg_rom asegs) ->
      nst mc -> stk asegs mc lo (bv_unsigned spw) ->
      uframe mc spw mw bw ew xg ng j6 slv s4 s3 s2 s1 s0 ra ->
      cregs r -> ra0 r = a0 -> ra1 r = Z_to_bv 64 q -> ra2 r = Z_to_bv 64 ev -> ra3 r = Z_to_bv 64 loc ->
      p <= q <= e -> 1 <= ev < 1000 -> 2 <= loc < 2^32 ->
      as_SR H POST (mkCfg msF mo).
Proof.
