    (* [comment removed for export] *)
    Lemma push_fin : forall (entry k rasite : Z) msF mo mc (r : rv) Fx fcx mw bw ew xg ng j6 (pay : word) (p' : Z),
      (entry = A_PUSH_I64 /\ k = 2 /\ rasite = 0x10117c) \/ (entry = A_PUSH_DBL /\ k = 4 /\ rasite = 0x10100c) ->
      as_AKREL H s (mkCfg msF mo) -> as_MPRES H mo0 mo ->
      as_VIS H s msF = MS (mkRr r) Fx (wz entry) fcx None mc (seg_rom asegs) -> frm0 fcx ->
      nst mc -> stk asegs mc lo (bv_unsigned spw) ->
      uframe mc spw mw bw ew xg ng j6 pay s4 s3 s2 s1 s0 ra ->
      bregs r -> rra r = Z_to_bv 64 rasite -> ra0 r = a0 -> ra1 r = Z_to_bv 64 (bv_unsigned spw + 24) -> ra2 r = Z_to_bv 64 (pa + 56) ->
      rs1 r = Z_to_bv 64 p' -> p < p' <= e ->
