    (* [comment removed for export] *)
    Lemma xlh_loopn : forall (n : nat) (q : Z) msF mo mc (r : rv) Fx (mw : word) (bc expo xc xn : Z) j6 slv,
      (Z.to_nat (e - q) <= n)%nat ->
      as_AKREL H s (mkCfg msF mo) -> as_MPRES H mo0 mo ->
      as_VIS H s msF = MS (mkRr r) Fx (Z_to_bv 64 0x100e10) fc None mc (seg_rom asegs) ->
      nst mc -> stk asegs mc lo (bv_unsigned spw) -> pinb mc p0 e inb -> pshb mc p0 e ->
      uframe mc spw mw (Z_to_bv 64 bc) (Z_to_bv 64 xc) (b8 xn) (b8 0) j6 slv s4 s3 s2 s1 s0 ra ->
      bregs r -> rs1 r = Z_to_bv 64 q -> ra0 r = Z_to_bv 64 q -> ra2 r = Z_to_bv 64 expo ->
      ra1 r = Z_to_bv 64 9 -> ra3 r = Z_to_bv 64 55 -> ra4 r = Z_to_bv 64 2147483647 -> ra5 r = Z_to_bv 64 214748364 -> ra6 r = Z_to_bv 64 10 ->
      p + 2 <= q < e -> -2^31 + 1 < bc <= 0 -> 0 <= expo < 2^31 -> 0 <= xc < 2^31 -> 0 <= xn <= 1 ->
