    Lemma frh_loop : forall (q : Z) msF mo mc (r : rv) Fx (mw mw0 : word) (bias bc : Z) j6 slv,
      as_AKREL H s (mkCfg msF mo) -> as_MPRES H mo0 mo ->
      as_VIS H s msF = MS (mkRr r) Fx (Z_to_bv 64 0x100a58) fc None mc (seg_rom asegs) ->
      nst mc -> stk asegs mc lo (bv_unsigned spw) -> pinb mc p0 e inb -> pshb mc p0 e ->
      uframe mc spw mw0 (Z_to_bv 64 bc) (Z_to_bv 64 0) (b8 0) (b8 0) j6 slv s4 s3 s2 s1 s0 ra ->
      bregs r -> rs1 r = Z_to_bv 64 q -> ra0 r = Z_to_bv 64 q -> ra2 r = mw -> ra1 r = Z_to_bv 64 bias ->
      ra3 r = Z_to_bv 64 9 -> ra4 r = Z_to_bv 64 (-2147483647) -> ra5 r = Z_to_bv 64 10 ->
      p + 2 <= q < e -> p - q <= bias <= 0 -> -2^31 + 1 < bc <= 0 ->
      as_SR H POST (mkCfg msF mo).
Proof.
