    Lemma frl0_fin : forall msF mo mc (r : rv) Fx (mw : word) (bias : Z) j6 slv (q : Z),
      as_AKREL H s (mkCfg msF mo) -> as_MPRES H mo0 mo ->
      as_VIS H s msF = MS (mkRr r) Fx (Z_to_bv 64 0x100a38) fc None mc (seg_rom asegs) ->
      nst mc -> stk asegs mc lo (bv_unsigned spw) -> pinb mc p0 e inb -> pshb mc p0 e ->
      uframe mc spw mw (Z_to_bv 64 bias) (Z_to_bv 64 0) (b8 0) (b8 0) j6 slv s4 s3 s2 s1 s0 ra ->
      bregs r -> rs1 r = Z_to_bv 64 q -> p + 2 <= q < e -> p - q <= bias <= 0 ->
      as_SR H POST (mkCfg msF mo).
