    Lemma zput0_fin : forall msF mo mc (r : rv) Fx (acc : word) j6 slv (k i : Z),
      as_AKREL H s (mkCfg msF mo) -> as_MPRES H mo0 mo ->
      as_VIS H s msF = MS (mkRr r) Fx (Z_to_bv 64 0x101444) fc None mc (seg_rom asegs) ->
      nst mc -> stk asegs mc lo (bv_unsigned spw) -> pinb mc p0 e inb -> pshb mc p0 e ->
      uframe mc spw (Z_to_bv 64 0) (Z_to_bv 64 0) (Z_to_bv 64 0) (b8 0) (b8 0) j6 slv s4 s3 s2 s1 s0 ra ->
      bregs r -> ra1 r = Z_to_bv 64 (p + 2) -> ra3 r = Z_to_bv 64 k -> ra2 r = Z_to_bv 64 i -> ra4 r = acc -> ra5 r = Z_to_bv 64 (k + - i) ->
      p + 33 <= e -> 1 <= k <= 16 -> 0 <= i <= k -> k <= i + 3 ->
