    Lemma zpul_loop_n : forall (n : nat) (i : Z) msF mo mc (r : rv) Fx (acc : word) j6 slv (k : Z),
      (Z.to_nat (k - i) <= n)%nat ->
      as_AKREL H s (mkCfg msF mo) -> as_MPRES H mo0 mo ->
      as_VIS H s msF = MS (mkRr r) Fx (Z_to_bv 64 0x101370) fc None mc (seg_rom asegs) ->
      nst mc -> stk asegs mc lo (bv_unsigned spw) -> pinb mc p0 e inb -> pshb mc p0 e ->
      uframe mc spw (Z_to_bv 64 0) (Z_to_bv 64 0) (Z_to_bv 64 0) (b8 0) (b8 0) j6 slv s4 s3 s2 s1 s0 ra ->
      bregs r -> ra1 r = Z_to_bv 64 (p + 2) -> ra3 r = Z_to_bv 64 k -> ra2 r = Z_to_bv 64 i -> ra4 r = acc ->
      ra5 r = Z_to_bv 64 (k + - i) -> ra6 r = Z_to_bv 64 10 -> ra7 r = Z_to_bv 64 3 ->
      p + 33 <= e -> 4 <= k <= 16 -> 0 <= i -> i + 4 <= k ->
      as_SR H POST (mkCfg msF mo).
